CREATE PROCEDURE `QuerySyndicateRankInformation`()
BEGIN

	SELECT 
		id Id,
        name `Name`,
        leader_id `LeaderId`,
        amount `Amount`,
        money `Money`,
        emoney `ConquerPoints`,
        synrank `Level`,
        IF(del_flag IS NULL, 0, 1) `DelFlag`
    FROM cq_syndicate;

END ;;
