CREATE PROCEDURE `QueryTradeHistoryById`(IN idTrade INT)
BEGIN
	SELECT 
		tradeitem.*,
        itemtype.name `ItemName`
	FROM 
		cq_trade_item tradeitem
	LEFT JOIN cq_itemtype itemtype ON itemtype.id = tradeitem.itemtype
	WHERE 
		trade_id=idTrade;
END ;;
DELIMITER ;
