CREATE PROCEDURE `WinSyndicateProc`()
BEGIN
	INSERT INTO winsyndicate SELECT 
		NULL,
		NOW(),
		syndicate.id,
		syndicate.name,
		syndicate.leader_id,
		syndicate.leader_name,
		syndicate.amount,
		syndicate.money
	FROM cq_dynanpc dynanpc
		LEFT JOIN cq_syndicate syndicate ON syndicate.id = dynanpc.ownerid
	WHERE dynanpc.id = 810;
END ;;
DELIMITER ;
